var e=[{id:`free`,name:`Explorer`,price:`CHF 0`,cadence:`einmalig`,tokens:`4 Start-Tokens`,audience:`Beide Studios kennenlernen`,features:[`3D- und Motivvorschauen testen`,`Physische Produkte bestellen`,`Kein STL- oder HD-Dateiexport`]},{id:`3d-studio`,name:`3D Studio`,price:`CHF 19`,cadence:`/ Monat`,tokens:`20 Tokens monatlich`,audience:`Für eigene 3D-Modelle`,features:[`AB3D 3D Design Studio`,`STL-, 3MF- und GLB-Download`,`Druckprüfung und exakte Skalierung`]},{id:`cappatex`,name:`CAPPATEX`,price:`CHF 15`,cadence:`/ Monat`,tokens:`20 Tokens monatlich`,audience:`Für Motive auf Kleidung`,features:[`CAPPATEX Motiv-Studio`,`Druckfähige HD-Motivdateien`,`Produkt-Mockups und Platzierung`]},{id:`complete`,name:`Complete`,price:`CHF 29`,cadence:`/ Monat`,tokens:`40 Tokens monatlich`,audience:`Beide Studios in einem Abo`,features:[`3D Studio und CAPPATEX`,`Alle Datei- und Druckexporte`,`Gemeinsames Token-Guthaben`],popular:!0}],t=[[`1 Token`,`3D-Grundform oder CAPPATEX Motivvorschau`],[`2 Tokens`,`3D-Modell mit Textur oder direktes Foto-zu-3D`],[`3 Tokens`,`Kreative Fotointerpretation mit fertigem 3D-Modell`],[`2–3 Tokens`,`Exakte Skalierung, Prüfung und STL-/3MF-Druckpaket`]];function n(t){let n=t===`studio`?`3d-studio`:t===`pro`?`complete`:t;return e.find(e=>e.id===n)?.name||`Explorer`}export{n,t as r,e as t};